import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api from '../api/axios';
import { Container, Form, Button, Alert, Row, Col, Table, Modal, Spinner } from 'react-bootstrap';

const AdminPanel = () => {
  const navigate = useNavigate();
  const [classes, setClasses] = useState([]);
  const [positions, setPositions] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [schedule, setSchedule] = useState([]);
  
  // Формы для создания ученика/учителя
  const [studentForm, setStudentForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    class_id: '',
    email: ''
  });
  const [teacherForm, setTeacherForm] = useState({
    last_name: '',
    first_name: '',
    middle_name: '',
    position_ids: [],
    email: ''
  });
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  // Расписание
  const [selectedClassForSchedule, setSelectedClassForSchedule] = useState('');
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [newLesson, setNewLesson] = useState({
    date: '',
    day_of_week: '',
    lesson_number: 1,
    subject_id: '',
    teacher_id: '',
    class_id: '',
    homework: ''
  });

  useEffect(() => {
    fetchClasses();
    fetchPositions();
    fetchSubjects();
    fetchTeachers();
  }, []);

  useEffect(() => {
    if (selectedClassForSchedule) {
      fetchSchedule(selectedClassForSchedule);
    }
  }, [selectedClassForSchedule]);

  const fetchClasses = async () => {
    try {
      const res = await api.get('/director/classes');
      setClasses(res.data);
      if (res.data.length > 0) {
        setSelectedClassForSchedule(res.data[0].id);
      }
    } catch (err) {
      console.error('Ошибка загрузки классов:', err);
    }
  };

  const fetchPositions = async () => {
    try {
      const res = await api.get('/director/positions');
      setPositions(res.data);
    } catch (err) {
      console.error('Ошибка загрузки должностей:', err);
    }
  };

  const fetchSubjects = async () => {
    try {
      const res = await api.get('/schedule/subjects');
      setSubjects(res.data);
    } catch (err) {
      console.error('Ошибка загрузки предметов:', err);
    }
  };

  const fetchTeachers = async () => {
    try {
      const res = await api.get('/director/teachers');
      setTeachers(res.data);
    } catch (err) {
      console.error('Ошибка загрузки учителей:', err);
    }
  };

  const fetchSchedule = async (classId) => {
    setLoading(true);
    try {
      const res = await api.get('/schedule', {
        params: { class_id: classId }
      });
      setSchedule(res.data.schedule || []);
    } catch (err) {
      console.error('Ошибка загрузки расписания:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleStudentChange = (e) => {
    setStudentForm({ ...studentForm, [e.target.name]: e.target.value });
  };

  const handleTeacherChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (type === 'checkbox') {
      const posId = parseInt(value);
      setTeacherForm(prev => {
        const newIds = prev.position_ids.includes(posId)
          ? prev.position_ids.filter(id => id !== posId)
          : [...prev.position_ids, posId];
        return { ...prev, position_ids: newIds };
      });
    } else {
      setTeacherForm({ ...teacherForm, [name]: value });
    }
  };

  const createStudent = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/student', studentForm);
      setResult({ type: 'Ученик', ...res.data });
      setStudentForm({ last_name: '', first_name: '', middle_name: '', class_id: '', email: '' });
    } catch (err) {
      console.error('Ошибка:', err.response?.data);
      if (err.response?.data?.error === 'EMAIL_EXISTS') {
        setError('❌ Этот email уже используется. Пожалуйста, используйте другой email.');
      } else if (err.response?.data?.error === 'LOGIN_EXISTS') {
        setError('❌ Этот логин уже занят. Попробуйте снова.');
      } else {
        setError(err.response?.data?.error || 'Ошибка создания ученика');
      }
    }
  };

  const createTeacher = async (e) => {
    e.preventDefault();
    setError('');
    setResult(null);
    try {
      const res = await api.post('/director/teacher', teacherForm);
      setResult({ type: 'Учитель', ...res.data });
      setTeacherForm({ last_name: '', first_name: '', middle_name: '', position_ids: [], email: '' });
    } catch (err) {
      console.error('Ошибка:', err.response?.data);
      if (err.response?.data?.error === 'EMAIL_EXISTS') {
        setError('❌ Этот email уже используется. Пожалуйста, используйте другой email.');
      } else if (err.response?.data?.error === 'LOGIN_EXISTS') {
        setError('❌ Этот логин уже занят. Попробуйте снова.');
      } else {
        setError(err.response?.data?.error || 'Ошибка создания учителя');
      }
    }
  };

  const handleDateChange = (date) => {
    const dayNames = ['Воскресенье', 'Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота'];
    const dayOfWeek = dayNames[new Date(date).getDay()];
    setNewLesson({ ...newLesson, date, day_of_week: dayOfWeek });
  };

  const handleAddLesson = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');
    try {
      await api.post('/schedule', newLesson);
      setSuccess('Урок добавлен!');
      setShowScheduleModal(false);
      if (selectedClassForSchedule) {
        fetchSchedule(selectedClassForSchedule);
      }
      setNewLesson({
        date: '',
        day_of_week: '',
        lesson_number: 1,
        subject_id: '',
        teacher_id: '',
        class_id: '',
        homework: ''
      });
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка добавления урока');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteLesson = async (id) => {
    if (!window.confirm('Удалить урок?')) return;
    try {
      await api.delete(`/schedule/${id}`);
      setSuccess('Урок удалён');
      if (selectedClassForSchedule) {
        fetchSchedule(selectedClassForSchedule);
      }
    } catch (err) {
      setError('Ошибка удаления урока');
    }
  };

  const getTeacherName = (teacherId) => {
    const teacher = teachers.find(t => t.id === teacherId);
    return teacher ? `${teacher.last_name} ${teacher.first_name}` : 'Не назначен';
  };

  const getSubjectName = (subjectId) => {
    const subject = subjects.find(s => s.id === subjectId);
    return subject ? subject.name : 'Не назначен';
  };

  return (
    <Container className="mt-4">
      <h3>Админ-панель (Директор)</h3>
      
      <div className="mb-3">
        <Link to="/classes" className="btn btn-info me-2">
          Управление классами
        </Link>
      </div>
      {/* Раздел управления расписанием */}
      <hr className="my-4" />
      <h4>Управление расписанием</h4>
      
      <Row>
        <Col md={4}>
          <Form.Select 
            value={selectedClassForSchedule} 
            onChange={e => setSelectedClassForSchedule(e.target.value)}
          >
            {classes.map(c => (
              <option key={c.id} value={c.id}>{c.grade} класс</option>
            ))}
          </Form.Select>
        </Col>
        <Col md={4}>
          <Button variant="primary" onClick={() => setShowScheduleModal(true)}>
            + Добавить урок
          </Button>
        </Col>
      </Row>

      <div className="mt-3 table-responsive">
        <Table striped bordered hover size="sm">
          <thead>
            <tr>
              <th>Дата</th>
              <th>День</th>
              <th>№</th>
              <th>Предмет</th>
              <th>Учитель</th>
              <th>ДЗ</th>
              <th>Действия</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan="7" className="text-center"><Spinner animation="border" size="sm" /></td></tr>
            ) : schedule.length === 0 ? (
              <tr><td colSpan="7" className="text-center">Нет уроков</td></tr>
            ) : (
              schedule.map(item => (
                <tr key={item.id}>
                  <td>{new Date(item.date).toLocaleDateString('ru-RU')}</td>
                  <td>{item.day_of_week}</td>
                  <td>{item.lesson_number}</td>
                  <td>{getSubjectName(item.subject_id)}</td>
                  <td>{getTeacherName(item.teacher_id)}</td>
                  <td>{item.homework || '—'}</td>
                  <td>
                    <Button variant="danger" size="sm" onClick={() => handleDeleteLesson(item.id)}>
                      Удалить
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>
      </div>

      {/* Модальное окно добавления урока */}
      <Modal show={showScheduleModal} onHide={() => setShowScheduleModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Добавить урок</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form onSubmit={handleAddLesson}>
            <Form.Group className="mb-2">
              <Form.Label>Дата</Form.Label>
              <Form.Control
                type="date"
                value={newLesson.date}
                onChange={e => handleDateChange(e.target.value)}
                required
              />
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Номер урока</Form.Label>
              <Form.Select
                value={newLesson.lesson_number}
                onChange={e => setNewLesson({ ...newLesson, lesson_number: parseInt(e.target.value) })}
                required
              >
                {[1,2,3,4,5,6,7,8].map(n => (
                  <option key={n} value={n}>{n}</option>
                ))}
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Предмет</Form.Label>
              <Form.Select
                value={newLesson.subject_id}
                onChange={e => setNewLesson({ ...newLesson, subject_id: parseInt(e.target.value) })}
                required
              >
                <option value="">Выберите предмет</option>
                {subjects.map(s => (
                  <option key={s.id} value={s.id}>{s.name}</option>
                ))}
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Учитель</Form.Label>
              <Form.Select
                value={newLesson.teacher_id}
                onChange={e => setNewLesson({ ...newLesson, teacher_id: parseInt(e.target.value) })}
                required
              >
                <option value="">Выберите учителя</option>
                {teachers.map(t => (
                  <option key={t.id} value={t.id}>
                    {t.last_name} {t.first_name} {t.middle_name}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Класс</Form.Label>
              <Form.Select
                value={newLesson.class_id}
                onChange={e => setNewLesson({ ...newLesson, class_id: parseInt(e.target.value) })}
                required
              >
                <option value="">Выберите класс</option>
                {classes.map(c => (
                  <option key={c.id} value={c.id}>{c.grade} класс</option>
                ))}
              </Form.Select>
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Домашнее задание</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                value={newLesson.homework}
                onChange={e => setNewLesson({ ...newLesson, homework: e.target.value })}
                placeholder="Домашнее задание"
              />
            </Form.Group>

            <Button type="submit" variant="primary" disabled={loading}>
              {loading ? 'Сохранение...' : 'Сохранить'}
            </Button>
          </Form>
        </Modal.Body>
      </Modal>
      
      {error && <Alert variant="danger">{error}</Alert>}
      {success && <Alert variant="success">{success}</Alert>}
      {result && (
        <Alert variant="success">
          <strong>{result.type} создан(а)!</strong><br />
          Логин: <code>{result.login}</code><br />
          Пароль: <code>{result.password}</code><br />
          (Сообщите эти данные пользователю)
        </Alert>
      )}

      <Row>
        {/* Создание ученика */}
        <Col md={6}>
          <h5>Создать ученика</h5>
          <Form onSubmit={createStudent}>
            <Form.Group className="mb-2">
              <Form.Control
                name="last_name"
                placeholder="Фамилия"
                value={studentForm.last_name}
                onChange={handleStudentChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="first_name"
                placeholder="Имя"
                value={studentForm.first_name}
                onChange={handleStudentChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="middle_name"
                placeholder="Отчество"
                value={studentForm.middle_name}
                onChange={handleStudentChange}
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Select
                name="class_id"
                value={studentForm.class_id}
                onChange={handleStudentChange}
                required
              >
                <option value="">Выберите класс</option>
                {classes.map(cls => (
                  <option key={cls.id} value={cls.id}>
                    {cls.grade} класс
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="email"
                placeholder="Email (необязательно)"
                value={studentForm.email}
                onChange={handleStudentChange}
              />
            </Form.Group>
            <Button type="submit" variant="success">Создать ученика</Button>
          </Form>
        </Col>

        {/* Создание учителя */}
        <Col md={6}>
          <h5>Создать учителя</h5>
          <Form onSubmit={createTeacher}>
            <Form.Group className="mb-2">
              <Form.Control
                name="last_name"
                placeholder="Фамилия"
                value={teacherForm.last_name}
                onChange={handleTeacherChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="first_name"
                placeholder="Имя"
                value={teacherForm.first_name}
                onChange={handleTeacherChange}
                required
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="middle_name"
                placeholder="Отчество"
                value={teacherForm.middle_name}
                onChange={handleTeacherChange}
              />
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Label>Должности (выберите несколько)</Form.Label>
              <div style={{ maxHeight: '200px', overflowY: 'auto', border: '1px solid #ccc', padding: '10px', borderRadius: '5px' }}>
                {positions.map(p => (
                  <Form.Check
                    key={p.id}
                    type="checkbox"
                    label={p.name}
                    value={p.id}
                    checked={teacherForm.position_ids.includes(p.id)}
                    onChange={handleTeacherChange}
                    name="position_ids"
                  />
                ))}
              </div>
            </Form.Group>
            <Form.Group className="mb-2">
              <Form.Control
                name="email"
                placeholder="Email (необязательно)"
                value={teacherForm.email}
                onChange={handleTeacherChange}
              />
            </Form.Group>
            <Button type="submit" variant="primary">Создать учителя</Button>
          </Form>
        </Col>
      </Row>

      
    </Container>
  );
};

export default AdminPanel;
